def classify(path):
 if path=='.pkgre-js-site.json':return 'generated-site-inventory'
 if path=='pkgre-js':return 'packument'
 if path.startswith('packages/'):return 'archive-object'
 if path.startswith('v1/js/main/'):return 'legacy-redirect-marker'
 if path=='index.html':return 'landing-page'
 if path=='.nojekyll':return 'provider-control'
 if path=='origin-health/v1.txt':return 'legacy-origin-canary'
 if path=='nonproduction/redirect-marker-fixture-v0/index.html':return 'nonproduction-fixture'
 raise AssertionError(path)
def content_type(cls):return {'generated-site-inventory':'application/json; charset=utf-8','packument':'application/json; charset=utf-8','archive-object':'application/octet-stream','legacy-redirect-marker':'text/html; charset=utf-8','landing-page':'text/html; charset=utf-8','provider-control':'application/octet-stream','legacy-origin-canary':'text/plain; charset=utf-8','nonproduction-fixture':'text/html; charset=utf-8'}[cls]
